package com.lingdong.learning.student.application;
import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.init.ScriptUtils;import org.springframework.core.io.ClassPathResource;
import com.lingdong.learning.student.infrastructure.persistence.*;import com.lingdong.learning.student.domain.Student;import com.lingdong.learning.organization.domain.Organization;import com.lingdong.learning.auth.application.AuthenticatedUser;import com.lingdong.learning.auth.domain.AuthClientType;import com.lingdong.learning.datascope.application.OrganizationDataScope;import java.util.List;
class StudentNumberTransactionTest {
 static class Store extends AcademicMetadataStore {boolean fail=true;boolean failAudit=false;Store(JdbcTemplate jdbc){super(jdbc);}public void insertEnrollment(long student,long institution,String number){super.insertEnrollment(student,institution,number);if(fail)throw new IllegalStateException("after real enrollment metadata insert");}public void recordAudit(String kind,long target,long scope,int version,long actor,String before,String after){super.recordAudit(kind,target,scope,version,actor,before,after);if(failAudit)throw new IllegalStateException("after real audit insert");}}
 @Test void failedNumberWriteRollsBackAndRetrySucceeds() throws Exception {
  try(var c=new AnnotationConfigApplicationContext(AcademicMetadataTransactionTest.Config.class)) {
   var db=c.getBean(JdbcTemplate.class);db.execute("CREATE TABLE sys_organization(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE edu_student(id BIGINT PRIMARY KEY)");try(var connection=c.getBean(javax.sql.DataSource.class).getConnection()){ScriptUtils.executeSqlScript(connection,new ClassPathResource("db/migration/V134__academic_class_and_enrollment_metadata.sql"));}
   db.update("INSERT INTO sys_organization VALUES(2)");db.update("INSERT INTO edu_student VALUES(10)");
   var f=c.getBean(AcademicMetadataTransactionTest.Fixture.class);var students=mock(StudentMapper.class);var relations=mock(StudentOrganizationMapper.class);var store=new Store(db);var actor=new AuthenticatedUser(1L,2L,"actor","actor",AuthClientType.MINIAPP,List.of());var scope=OrganizationDataScope.all(false);
   when(students.findByIdForUpdate(10L)).thenAnswer(i->{db.queryForObject("SELECT id FROM edu_student WHERE id=10 FOR UPDATE",Long.class);return Student.create(10L,"child",null,11L);});when(relations.findActiveOrganizationIdsForUpdate(10L)).thenReturn(List.of(2L));when(f.orgs.findByIdForUpdate(2L)).thenReturn(Organization.create(2L,null,"ROOT","S","school","SCHOOL","/2/",1,null));when(f.access.scope(actor)).thenReturn(scope);when(relations.existsActiveEnrollmentInScope(10L,2L,scope)).thenReturn(true);
   c.registerBean("studentNumberService",StudentNumberService.class,()->new StudentNumberService(store,f.access,f.orgs,students,relations,f.features));var service=c.getBean(StudentNumberService.class);assertThat(org.springframework.aop.support.AopUtils.isAopProxy(service)).isTrue();
   assertThatThrownBy(()->service.update(actor,10L,2L,"A001",0)).isInstanceOf(IllegalStateException.class);assertThat(db.queryForObject("SELECT COUNT(*) FROM edu_student_enrollment_metadata",Integer.class)).isZero();store.fail=false;var result=service.update(actor,10L,2L," A001 ",0);assertThat(result.studentNumber()).isEqualTo("A001");assertThat(result.versionNo()).isEqualTo(1);
  }
 }
 @Test void concurrentSameEnrollmentVersionHasOneWinner() throws Exception {
  try(var c=new AnnotationConfigApplicationContext(AcademicMetadataTransactionTest.Config.class)) {
   var db=c.getBean(JdbcTemplate.class);db.execute("CREATE TABLE sys_organization(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE edu_student(id BIGINT PRIMARY KEY)");try(var connection=c.getBean(javax.sql.DataSource.class).getConnection()){ScriptUtils.executeSqlScript(connection,new ClassPathResource("db/migration/V134__academic_class_and_enrollment_metadata.sql"));}
   db.update("INSERT INTO sys_organization VALUES(2)");db.update("INSERT INTO edu_student VALUES(10)");
   var f=c.getBean(AcademicMetadataTransactionTest.Fixture.class);var students=mock(StudentMapper.class);var relations=mock(StudentOrganizationMapper.class);var store=new Store(db);var actor=new AuthenticatedUser(1L,2L,"actor","actor",AuthClientType.MINIAPP,List.of());var scope=OrganizationDataScope.all(false);
   when(students.findByIdForUpdate(10L)).thenAnswer(i->{db.queryForObject("SELECT id FROM edu_student WHERE id=10 FOR UPDATE",Long.class);return Student.create(10L,"child",null,11L);});when(relations.findActiveOrganizationIdsForUpdate(10L)).thenReturn(List.of(2L));when(f.orgs.findByIdForUpdate(2L)).thenReturn(Organization.create(2L,null,"ROOT","S","school","SCHOOL","/2/",1,null));when(f.access.scope(actor)).thenReturn(scope);when(relations.existsActiveEnrollmentInScope(10L,2L,scope)).thenReturn(true);
   c.registerBean("studentNumberService",StudentNumberService.class,()->new StudentNumberService(store,f.access,f.orgs,students,relations,f.features));var service=c.getBean(StudentNumberService.class);assertThat(org.springframework.aop.support.AopUtils.isAopProxy(service)).isTrue();
   store.fail=false;var ready=new java.util.concurrent.CountDownLatch(2);var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
   try {java.util.concurrent.Callable<String> operation=()->{ready.countDown();if(!start.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("start timeout");try{service.update(actor,10L,2L,"A001",0);return "SUCCESS";}catch(IllegalStateException conflict){if(!conflict.getMessage().contains("刷新"))throw conflict;return "CONFLICT";}};
    var first=pool.submit(operation);var second=pool.submit(operation);assertThat(ready.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();start.countDown();assertThat(List.of(first.get(10,java.util.concurrent.TimeUnit.SECONDS),second.get(10,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder("SUCCESS","CONFLICT");assertThat(db.queryForObject("SELECT COUNT(*) FROM edu_student_enrollment_metadata",Integer.class)).isEqualTo(1);assertThat(db.queryForObject("SELECT version_no FROM edu_student_enrollment_metadata",Integer.class)).isEqualTo(1);
   }finally{start.countDown();pool.shutdownNow();}
  }
 }
 @Test void auditFailureRollsBackBothConfigurationAndHistory() throws Exception {
  try(var c=new AnnotationConfigApplicationContext(AcademicMetadataTransactionTest.Config.class)) {
   var db=c.getBean(JdbcTemplate.class);db.execute("CREATE TABLE sys_organization(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY)");db.execute("CREATE TABLE edu_student(id BIGINT PRIMARY KEY)");try(var connection=c.getBean(javax.sql.DataSource.class).getConnection()){ScriptUtils.executeSqlScript(connection,new ClassPathResource("db/migration/V134__academic_class_and_enrollment_metadata.sql"));}
   db.update("INSERT INTO sys_organization VALUES(2)");db.update("INSERT INTO edu_student VALUES(10)");
   var f=c.getBean(AcademicMetadataTransactionTest.Fixture.class);var students=mock(StudentMapper.class);var relations=mock(StudentOrganizationMapper.class);var store=new Store(db);var actor=new AuthenticatedUser(1L,2L,"actor","actor",AuthClientType.MINIAPP,List.of());var scope=OrganizationDataScope.all(false);
   when(students.findByIdForUpdate(10L)).thenAnswer(i->{db.queryForObject("SELECT id FROM edu_student WHERE id=10 FOR UPDATE",Long.class);return Student.create(10L,"child",null,11L);});when(relations.findActiveOrganizationIdsForUpdate(10L)).thenReturn(List.of(2L));when(f.orgs.findByIdForUpdate(2L)).thenReturn(Organization.create(2L,null,"ROOT","S","school","SCHOOL","/2/",1,null));when(f.access.scope(actor)).thenReturn(scope);when(relations.existsActiveEnrollmentInScope(10L,2L,scope)).thenReturn(true);
   c.registerBean("studentNumberService",StudentNumberService.class,()->new StudentNumberService(store,f.access,f.orgs,students,relations,f.features));var service=c.getBean(StudentNumberService.class);assertThat(org.springframework.aop.support.AopUtils.isAopProxy(service)).isTrue();
   store.fail=false;store.failAudit=true;
   assertThatThrownBy(()->service.update(actor,10L,2L,"A001",0)).isInstanceOf(IllegalStateException.class);assertThat(db.queryForObject("SELECT COUNT(*) FROM edu_student_enrollment_metadata",Integer.class)).isZero();assertThat(db.queryForObject("SELECT COUNT(*) FROM edu_academic_metadata_audit",Integer.class)).isZero();store.failAudit=false;var result=service.update(actor,10L,2L," A001 ",0);assertThat(result.studentNumber()).isEqualTo("A001");assertThat(result.versionNo()).isEqualTo(1);
   assertThat(db.queryForObject("SELECT COUNT(*) FROM edu_academic_metadata_audit",Integer.class)).isEqualTo(1);
  }
 }
}
